"""The `rllab` command: parses a trigger, calls its pipeline entry, prints the result (AD-10).

`root` is the project folder holding `runs/` and `reports/`; it defaults to the current one.
"""

import argparse
import sys
from collections.abc import Callable, Sequence
from pathlib import Path

from rllab.cli.pipelines.pl04_watch import run_watch
from rllab.cli.pipelines.pl05_chart import run_chart
from rllab.cli.pipelines.pl06_evaluate import run_evaluate
from rllab.train import run_batch, run_check

Handler = Callable[[argparse.Namespace], object]


def main(argv: Sequence[str] | None = None) -> int:
    """Run one subcommand; print its result, or one line naming the error and return 1."""
    args = _parser().parse_args(argv)
    handler: Handler = args.handler
    try:
        result = handler(args)
    except Exception as exc:  # every failure is reported, none is a traceback (cli.main)
        message = str(exc).splitlines()[0] if str(exc) else ""
        print(f"rllab {args.command}: {type(exc).__name__}: {message}", file=sys.stderr)
        return 1
    for item in result if isinstance(result, list) else [result]:
        print(item)
    return 0


def seed_list(text: str) -> list[int]:
    """`1-5` or `1,3,7` as a list of seeds."""
    if "-" in text:
        first, last = text.split("-", 1)
        return list(range(int(first), int(last) + 1))
    return [int(s) for s in text.split(",")]


def _check(a: argparse.Namespace) -> object:
    return run_check(a.config, a.seed)


def _train(a: argparse.Namespace) -> object:
    return run_batch(a.config, [a.seed], a.root, check_seed=a.check_seed)


def _batch(a: argparse.Namespace) -> object:
    return run_batch(a.config, a.seeds, a.root, workers=a.workers, check_seed=a.check_seed)


def _watch(a: argparse.Namespace) -> object:
    return run_watch(a.run)


def _chart(a: argparse.Namespace) -> object:
