from rllab.cli.pipelines.pl05_chart import run_chart
from rllab.cli.pipelines.pl06_evaluate import run_evaluate
from rllab.train import run_batch, run_check

Handler = Callable[[argparse.Namespace], object]


def main(argv: Sequence[str] | None = None) -> int:
    """Run one subcommand; print its result, or one line naming the error and return 1."""
    args = _parser().parse_args(argv)
    handler: Handler = args.handler
    try:
        result = handler(args)
    except Exception as exc:  # every failure is reported, none is a traceback (cli.main)
        message = str(exc).splitlines()[0] if str(exc) else ""
        print(f"rllab {args.command}: {type(exc).__name__}: {message}", file=sys.stderr)
        return 1
    for item in result if isinstance(result, list) else [result]:
