"""Contract-test helpers: a JSON Schema check for the subset the schemas use, and a JSON
comparison that allows float32 rounding (arrays decode as float32)."""

import math
from collections.abc import Callable
from typing import Any

import pytest

JSON_TYPES: dict[str, Callable[[Any], bool]] = {
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "string": lambda v: isinstance(v, str),
    "boolean": lambda v: isinstance(v, bool),
    "integer": lambda v: isinstance(v, int) and not isinstance(v, bool),
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "null": lambda v: v is None,
}


def schema_errors(value: Any, schema: dict[str, Any], where: str = "$") -> list[str]:
    """Where `value` breaks `schema` (type, enum, anyOf, properties, items, item counts)."""
    if "anyOf" in schema:
        fits = any(not schema_errors(value, s, where) for s in schema["anyOf"])
        return [] if fits else [f"{where}: fits no anyOf branch"]
    if "enum" in schema and value not in schema["enum"]:
        return [f"{where}: {value!r} not in {schema['enum']}"]
    kind = schema.get("type")
    if kind and not JSON_TYPES[kind](value):
        return [f"{where}: expected {kind}, got {type(value).__name__}"]
    if kind == "object":
        return _object_errors(value, schema, where)
    if kind == "array":
        return _array_errors(value, schema, where)
    return []


def _object_errors(value: dict[str, Any], schema: dict[str, Any], where: str) -> list[str]:
    props = schema.get("properties", {})
    extra = schema.get("additionalProperties", True)
    errors = [f"{where}: missing {k}" for k in schema.get("required", []) if k not in value]
    for key, item in value.items():
        if key in props:
            errors += schema_errors(item, props[key], f"{where}.{key}")
        elif extra is False:
            errors.append(f"{where}: unexpected {key}")
        elif isinstance(extra, dict):
            errors += schema_errors(item, extra, f"{where}.{key}")
    return errors


def _array_errors(value: list[Any], schema: dict[str, Any], where: str) -> list[str]:
    errors = []
    if len(value) < schema.get("minItems", 0) or len(value) > schema.get("maxItems", len(value)):
        errors.append(f"{where}: {len(value)} items")
    prefix = schema.get("prefixItems", [])
    for i, item in enumerate(value):
        item_schema = prefix[i] if i < len(prefix) else schema.get("items", {})
        errors += schema_errors(item, item_schema, f"{where}[{i}]")
    return errors


def same_json(a: Any, b: Any) -> bool:
    """Equal JSON values, numbers within float32 precision, NaN equal to NaN."""
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same_json(a[k], b[k]) for k in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same_json(x, y) for x, y in zip(a, b, strict=True))
    numbers = JSON_TYPES["number"]
    if numbers(a) and numbers(b):
        both_nan = math.isnan(a) and math.isnan(b)
        return both_nan or math.isclose(a, b, rel_tol=1e-6, abs_tol=1e-9)
    return type(a) is type(b) and a == b


@pytest.fixture
def validate() -> Callable[[Any, dict[str, Any]], list[str]]:
    return schema_errors


@pytest.fixture
def same() -> Callable[[Any, Any], bool]:
    return same_json

