"""Every contract sample validates against its schema and round-trips through its type."""

import importlib
import json
from dataclasses import fields, is_dataclass
from pathlib import Path
from typing import Any

import pytest

from rllab.core.codec import decode, to_json
from rllab.core.doubles import CONTRACTS

M1_FOLDERS = {
    "core": "ActionSpace TeamSpec WorldSpec Step EpisodeResult DrawState Frame Episode World "
    "Policy play_episode EVAL_SEEDS FINAL_SEEDS Output MethodConfig RunConfig",
    "worlds": "make CheckWorld",
    "baselines": "RandomPolicy RulePolicy rule_for BaselineMeans baseline_means",
    "methods": "Transition Learner make_learner load_policy",
    "train": "load_run_configs run_check run_train run_batch CheckResult",
    "runlog": "RunRecord EvalPoint Checkpoint Run RunWriter find_runs open_run Progress progress",
    "charts": "learning_curve",
    "evaluate": "Comparison Summary final_evaluation",
}
TYPE_FOLDERS = sorted(p for p in CONTRACTS.iterdir() if (p / "schema.json").is_file())
SAMPLES = [s for folder in TYPE_FOLDERS for s in sorted((folder / "samples").glob("*.json"))]


def load(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def symbol(folder: Path) -> Any:
    component, name = folder.name.split(".")
    return getattr(importlib.import_module(f"rllab.{component}"), name)


def sample_id(path: Path) -> str:
    return f"{path.parent.parent.name}/{path.stem}"


def test_every_m1_contract_symbol_has_its_folder() -> None:
    expected = {f"{c}.{name}" for c, names in M1_FOLDERS.items() for name in names.split()}
    present = {p.name for p in CONTRACTS.iterdir() if p.is_dir()}
    assert expected - present == set()


@pytest.mark.parametrize("folder", TYPE_FOLDERS, ids=lambda p: p.name)
def test_every_type_folder_has_a_sample(folder: Path) -> None:
    assert list((folder / "samples").glob("*.json"))


@pytest.mark.parametrize("path", SAMPLES, ids=sample_id)
def test_sample_validates_against_its_schema(path: Path, validate: Any) -> None:
    schema = load(path.parent.parent / "schema.json")
    assert validate(load(path), schema) == []


@pytest.mark.parametrize("path", SAMPLES, ids=sample_id)
def test_sample_round_trips_through_its_type(path: Path, same: Any) -> None:
    data, tp = load(path), symbol(path.parent.parent)
    if isinstance(tp, tuple):  # a seed set: the sample is the constant itself
        assert data == list(tp)
    else:
        assert same(to_json(decode(tp, data)), data)


@pytest.mark.parametrize(
    "folder", [f for f in TYPE_FOLDERS if is_dataclass(symbol(f))], ids=lambda p: p.name
)
def test_schema_lists_the_dataclass_fields(folder: Path) -> None:
    schema = load(folder / "schema.json")
    assert list(schema["properties"]) == [f.name for f in fields(symbol(folder))]


def test_schema_rejects_a_sample_missing_a_field(validate: Any) -> None:
    folder = CONTRACTS / "core.WorldSpec"
    data = load(folder / "samples" / "snake.json")
    del data["obs_len"]
    assert validate(data, load(folder / "schema.json")) == ["$: missing obs_len"]


def test_decode_refuses_a_value_of_the_wrong_type() -> None:
    data = load(CONTRACTS / "train.CheckResult" / "samples" / "dqn_pass.json")
    with pytest.raises(TypeError):
        decode(symbol(CONTRACTS / "train.CheckResult"), {**data, "passed": "yes"})


def test_action_space_samples_decode_to_their_member() -> None:
    action_space = symbol(CONTRACTS / "core.ActionSpace")
    snake = decode(action_space, load(CONTRACTS / "core.ActionSpace" / "samples" / "snake.json"))
    fish = decode(action_space, load(CONTRACTS / "core.ActionSpace" / "samples" / "fish.json"))
    assert (type(snake).__name__, type(fish).__name__) == ("Discrete", "Box")

