    assert list(schema["properties"]) == [f.name for f in fields(symbol(folder))]


def test_schema_rejects_a_sample_missing_a_field(validate: Any) -> None:
    folder = CONTRACTS / "core.WorldSpec"
    data = load(folder / "samples" / "snake.json")
    del data["obs_len"]
    assert validate(data, load(folder / "schema.json")) == ["$: missing obs_len"]


def test_decode_refuses_a_value_of_the_wrong_type() -> None:
    data = load(CONTRACTS / "train.CheckResult" / "samples" / "dqn_pass.json")
    with pytest.raises(TypeError):
        decode(symbol(CONTRACTS / "train.CheckResult"), {**data, "passed": "yes"})


def test_action_space_samples_decode_to_their_member() -> None:
    action_space = symbol(CONTRACTS / "core.ActionSpace")
    snake = decode(action_space, load(CONTRACTS / "core.ActionSpace" / "samples" / "snake.json"))
    fish = decode(action_space, load(CONTRACTS / "core.ActionSpace" / "samples" / "fish.json"))
    assert (type(snake).__name__, type(fish).__name__) == ("Discrete", "Box")

